const app=document.querySelector('#app');
const activityDom=createActivityDomUpdater(document);
let classBlockDomKey=null,classPanelNode=null,classScrubGesture=null;
const courseSound=createCourseAudioUI({app});
const station=id=>stations.find(item=>item.id===id);
let journal=null,review=null,extraPanelOpen=false;
let world,lastTime=performance.now(),lastMap=0,toastTimer;
const mobileUI=createMobileUI({app,getState:()=>({...state,extraPanelOpen}),getStations:()=>stations,onChange:()=>sync()});
const mobileControls=createMobileControls({getWorld:()=>world,getState:()=>({...state,extraPanelOpen,mobileMenuOpen:mobileUI.menuOpen}),onInteract:()=>openStation(state.nearby),onExit:()=>closeTeaching()});
const performanceUI=createPerformanceCheckUI({app,getWorld:()=>world,onStart(){state.modal=null;render();},notify:message=>notify(message)});
const exercise=id=>{const e=activityById(id);return e?{...e,...equipmentPresentationFor(id,world?.getEquipmentSettings?.(id)||{})}:null;};
const isClassActivity=e=>!!e&&(e.stationId==='group-class'||e.facilityKind==='groupClass');
const hasCurrentClassPanel=id=>isClassActivity(state.active)&&state.active.id===id&&classPanelNode?.isConnected&&classPanelNode.dataset.classActivity===id;
const classLesson=e=>({...groupClassByKind(e.classKind||'warmup'),...e});
const classTime=value=>{const seconds=Math.max(0,Math.floor(Number(value)||0));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;};
const classStages={warmup:'暖身',main:'主要訓練',cooldown:'緩和'};
const classMuscleNames={chest:'胸部',back:'背部',shoulders:'肩部',biceps:'肱二頭肌',triceps:'肱三頭肌',forearms:'前臂',core:'軀幹',glutes:'臀部',quads:'股四頭肌',hamstrings:'腿後側',calves:'小腿',hipFlexors:'髖屈肌'};
function classMuscleInfo(e,segment){const primary=segment?.block?.primaryMuscles??segment?.primaryMuscles??e.muscleKeys,secondary=segment?.block?.secondaryMuscles??segment?.secondaryMuscles??e.secondaryMuscleKeys;return {primary,secondary,activationKind:segment?.block?.activationKind??segment?.activationKind??e.classFocus,label:primary.length?primary.map(key=>classMuscleNames[key]||key).join('、'):'本段以恢復、調整呼吸為主'};}
function classCourseState(e){const course=state.course||{},elapsed=Math.min(e.duration,Math.max(0,course.elapsed??state.classSegment?.elapsed??state.classPhase*e.duration));return {...course,elapsed,duration:e.duration,remaining:Math.max(0,course.remaining??e.duration-elapsed),complete:!!course.complete||state.activityStage==='completed',previewed:!!course.previewed};}
function classCards(items){return items.map(item=>{const e=classLesson(item);return `<article class="trial-exercise-card class-course-card" data-class-kind="${e.classKind}"><div class="catalog-item-top"><b>${icon(e.classKind==='dance'?'compass':e.classKind==='cycle'?'route':'fullbody')}</b><span class="catalog-type">${e.equipmentTag}</span></div><h3>${e.name}</h3><small>${e.english}</small><p>${e.summary}</p><div class="class-card-meta"><span>${e.level}</span><span>${e.courseBlocks.length} 個段落</span><span>全程 ${e.duration/60} 分鐘</span></div><div class="class-card-outline">${Object.entries(classStages).map(([stage,name])=>`<span>${name} ${e.courseBlocks.filter(b=>b.stage===stage).reduce((total,b)=>total+b.seconds,0)/60} 分</span>`).join('<i>→</i>')}</div><span class="trial-location">${icon('pin')}團體教室</span><div class="trial-card-actions"><button class="primary-button" data-demo="${e.id}">${icon('play')}加入課程</button><button class="secondary-button" data-target-exercise="${e.id}">${icon('route')}前往教室</button></div></article>`;}).join('');}
function classPlan(e){const current=classBlockAt(e,state.classPhase),enabled=['exercising','completed'].includes(state.activityStage);return `<section class="class-plan" aria-label="課程流程"><div class="class-section-heading"><h3>整堂課的安排</h3><small>${e.duration/60} 分鐘・${e.courseBlocks.length} 段</small></div><ol>${e.courseBlocks.map((block,index)=>`<li class="class-plan-item ${state.activityStage==='exercising'&&current?.index===index?'active':''}" data-class-block="${index}"><button data-class-phase="${block.start}" ${enabled?'':'disabled'} aria-label="預覽${block.label}" ${state.activityStage==='exercising'&&current?.index===index?'aria-current="step"':''}><b>${String(index+1).padStart(2,'0')}</b><span><small>${block.block}・${classTime(block.seconds)}</small><strong>${block.label}</strong><em>${block.description}</em></span>${icon('play')}</button></li>`).join('')}</ol><p>點段落或拖曳進度會切成預覽並暫停；預覽不算完整上課。就位與收器材另有進出動作。</p></section>`;}
function classActivationLabel(e,segment){const kind=classMuscleInfo(e,segment).activationKind;return kind==='support'?'主要支撐與參與':kind==='mobility'?'活動與伸展目標':'課程主要參與';}
function setClassBadgeLabel(label){const text=document.querySelector('.demo-badge .muscle-legend > span')?.lastChild;if(text?.nodeType===3&&text.textContent!==label)text.textContent=label;}
function classTeaching(item){
  const e=classLesson(item),playing=state.activityStage==='exercising',course=classCourseState(e),enabled=playing||course.complete,segment=state.classSegment||classBlockAt(e,state.classPhase),muscles=classMuscleInfo(e,segment),target=muscles.activationKind==='mobility',support=muscles.activationKind==='support';
  return `<aside class="station-panel facility-panel class-panel${course.complete?' class-completed':''}" data-class-activity="${e.id}" aria-label="${e.name}課程教學"><div class="station-top"><span class="eyebrow">肌動基地 / 團體課程</span><button class="icon-button dark" data-action="close-teaching" aria-label="離開課程">${icon('close')}</button></div><div class="station-title"><span class="station-index">34</span><div><small>${e.english}</small><h2>${e.name}</h2></div></div><div class="station-zone">${icon('pin')}團體教室<span>${e.equipmentTag}</span></div><div class="station-scroll">${teachingReferenceMarkup(e)}<div class="class-timing" aria-label="課程時間"><div><small>已進行</small><strong id="class-time-elapsed">${classTime(course.elapsed)}</strong></div><div><small>剩餘時間</small><strong id="class-time-remaining">${classTime(Math.ceil(course.remaining))}</strong></div><div><small>整堂課</small><strong>${e.duration/60} 分鐘</strong></div></div><section class="class-completion" id="class-completion" ${course.complete?'':'hidden'} data-previewed="${course.previewed}"><small>這堂課已到結尾</small><h3 id="class-completion-title">${course.previewed?'預覽已到課程結尾':'課程完成'}</h3><p id="class-completion-description">${course.previewed?'這次使用了跳段預覽，未算作完整上課。':'已依序走完暖身、主要訓練與緩和。'}</p><dl><div><dt>課表時間</dt><dd>${classTime(e.duration)}</dd></div><div><dt>本次播放</dt><dd id="class-attended-time">${classTime(course.attendedSeconds||0)}</dd></div></dl><p>這裡記錄的是遊戲播放進度，不是身體運動紀錄。按「已了解」保存動作學習，或先收好器材再離開。</p><div class="class-completion-actions"><button class="secondary-button" data-action="course-restart">再上一次</button><button class="secondary-button" data-action="course-leave">返回探索</button></div></section><div class="class-live-segment" role="status" aria-live="polite"><small id="class-segment-block">${playing?segment?.stageLabel||segment?.block:'準備加入'}</small><strong id="class-segment-title">${playing?segment?.label:'前往教室並就位'}</strong><p id="class-segment-description">${playing?segment?.description:'人物就位後，教練和學員會一起開始。'}</p><div class="class-segment-meta" aria-live="off"><span id="class-segment-time"></span><span id="class-repetition"></span></div></div><div class="class-next"><small>下一段</small><strong id="class-next-label">${segment?.nextBlock?.label||e.courseBlocks[1]?.label||'課程結束'}</strong></div>${courseSound.markup()}<p class="class-description">${e.summary}</p><p class="class-preview-note" id="class-preview-note">${course.previewed?'預覽模式：跳段或拖曳後，不會算成完整上課。':'依序上完暖身、主要訓練與緩和，時間到會結束。'}</p><div class="class-muscles"><div id="class-muscle-map" data-block-id="${e.id}:${segment?.index??0}">${muscleMap(muscles.primary,muscles.secondary)}</div><div class="muscle-legend"><span><i class="primary-swatch"></i><span id="class-activation-primary">${support?'主要支撐與參與':target?'活動與伸展目標':'課程主要參與'}</span></span><span><i class="secondary-swatch"></i>輔助與支撐</span></div><p><span id="class-muscle-label">${muscles.label}</span><small id="class-activation-note">${support?'標色顯示支撐與參與部位，不代表量測的出力強度。':target?'標色表示活動與伸展部位，不代表出力大小。':'圖中及人物標色會隨當前段落更新。'}</small></p></div>${classPlan(e)}<details class="class-cues"><summary>動作提醒</summary><ol class="teaching-steps">${e.steps.map((step,index)=>`<li><span>${String(index+1).padStart(2,'0')}</span><div><h3>${step.title}</h3><p>${step.text}</p></div></li>`).join('')}</ol><p>${e.range.cue}</p></details></div><div class="station-controls class-controls"><div class="activity-flow"><span>就位・拿取</span><i>→</i><span>暖身・主訓・緩和</span><i>→</i><span>收好・離開</span><strong id="activity-flow-status">準備加入</strong></div><div class="animation-control"><div class="animation-heading"><span><i class="live-dot"></i><strong>整堂課進度</strong></span><span id="pose-label">${playing?segment?.label:'準備加入'}</span></div><progress id="pose-progress" max="1" value="${state.classPhase||0}" aria-label="整堂課進度"></progress><div class="animation-buttons"><button data-action="pause" ${playing?'':'disabled'} class="play-control" aria-label="${state.paused?'播放示範':'暫停示範'}">${icon(state.paused?'play':'pause')}<span>${state.paused?'播放':'暫停'}</span></button><div class="speed-controls">${[.5,1].map(speed=>`<button data-speed="${speed}" ${playing?'':'disabled'} class="${state.speed===speed?'active':''}" aria-pressed="${state.speed===speed}">${speed===.5?'0.5× 慢速':'1× 正常'}</button>`).join('')}</div></div><div class="trial-pose-tools"><label>預覽課程段落<input type="range" ${enabled?'':'disabled'} id="pose-scrub" min="0" max="1" step="0.0005" value="${state.classPhase||0}" aria-label="調整課程進度"></label><button class="text-button" ${enabled?'':'disabled'} data-action="restart">${icon('reset')}從頭上課</button></div></div></div><div class="station-footer"><button class="primary-button full-width" data-action="learned" ${enabled?'':'disabled'}>${icon('check')}已了解這堂課 ${icon('arrow')}</button><p class="teaching-note">「已了解」記錄動作學習，不等於已完成整堂課。按 Esc 會先收好器材。<a href="${e.source.url}" target="_blank" rel="noopener noreferrer">課程參考 ↗</a></p></div></aside>`;
}
function updateClassProgress(phase,segment,label){
  if(!isClassActivity(state.active))return;
  const e=classLesson(state.active),block=classBlockAt(e,phase),playing=state.activityStage==='exercising',info=segment||block,course=classCourseState(e),byId=id=>document.getElementById(id);
  // Completion styling changes the range's track width. Keep that geometry
  // until the native pointer gesture ends; values and controls still update.
  if(hasCurrentClassPanel(state.active.id)&&classScrubGesture?.panel!==classPanelNode)classPanelNode.classList.toggle('class-completed',course.complete);
  const setText=(element,value)=>{if(element&&element.textContent!==value)element.textContent=value;};
  setText(byId('class-segment-title'),state.activityStage==='counting-in'?`準備開始・${course.countInRemaining||3}`:course.complete?'課程已結束':playing?info?.label||block?.label:label);
  setText(byId('class-segment-block'),state.activityStage==='counting-in'?'開始倒數':course.complete?'結束':playing?info?.stageLabel||block?.block:'準備／離開');
  setText(byId('class-segment-description'),state.activityStage==='counting-in'?'站穩、調整呼吸，跟著倒數一起開始。':course.complete?'可以先收好器材再返回探索，或重新開始這堂課。':playing?info?.description||block?.description:'人物正在就位或收回器材，完成後才會切換狀態。');
  setText(byId('class-time-elapsed'),classTime(course.elapsed));setText(byId('class-time-remaining'),classTime(Math.ceil(course.remaining)));
  setText(byId('class-next-label'),course.complete?'已到課程結尾':info?.nextBlock?.label||e.courseBlocks[(block?.index??-1)+1]?.label||'課程結束，準備收好器材');
  setText(byId('class-segment-time'),playing?`${classTime(info?.localSeconds||0)} / ${classTime(info?.block?.seconds||block?.seconds||0)}`:'');
  const cyclic=playing&&!/rest|hold|recovery|recover|breathe|side-left|side-right/.test(info?.motionId||'');
  setText(byId('class-repetition'),playing&&e.classKind==='cycle'?`${Math.round(info.cadenceRPM)} rpm・畫面踏頻`:cyclic&&info?.repetitions?`第 ${info.repetition||1} / ${info.repetitions} 趟`:'');
  setText(byId('class-preview-note'),course.previewed?'預覽模式：跳段或拖曳後，不會算成完整上課。':'依序上完暖身、主要訓練與緩和，時間到會結束。');
  const summary=byId('class-completion');if(summary){summary.hidden=!course.complete;summary.dataset.previewed=String(course.previewed);}
  setText(byId('class-completion-title'),course.previewed?'預覽已到課程結尾':'課程完成');
  setText(byId('class-completion-description'),course.previewed?'這次使用了跳段預覽，未算作完整上課。':'已依序走完暖身、主要訓練與緩和。');
  setText(byId('class-attended-time'),classTime(course.attendedSeconds||0));
  const muscleRoot=byId('class-muscle-map'),muscleId=`${e.id}:${info?.index??block?.index??0}`;if(muscleRoot&&muscleRoot.dataset.blockId!==muscleId){const muscles=classMuscleInfo(e,info);muscleRoot.innerHTML=muscleMap(muscles.primary,muscles.secondary);muscleRoot.dataset.blockId=muscleId;setText(byId('class-muscle-label'),muscles.label);setClassBadgeLabel(classActivationLabel(e,info));setText(byId('class-activation-primary'),muscles.activationKind==='support'?'主要支撐與參與':muscles.activationKind==='mobility'?'活動與伸展目標':'課程主要參與');setText(byId('class-activation-note'),muscles.activationKind==='support'?'標色顯示支撐與參與部位，不代表量測的出力強度。':muscles.activationKind==='mobility'?'標色表示活動與伸展部位，不代表出力大小。':'圖中及人物標色會隨當前段落更新。');}
  const blockDomKey=`${state.active.id}:${playing}:${block?.index}`;if(blockDomKey!==classBlockDomKey){classBlockDomKey=blockDomKey;document.querySelectorAll('[data-class-block]').forEach(item=>{const active=playing&&Number(item.dataset.classBlock)===block?.index;item.classList.toggle('active',active);const button=item.querySelector('button');if(active)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');});}
}
const title=s=>s.id==='dumbbell-curl'?'啞鈴訓練區':s.id==='cable-fly'?'龍門架訓練站':s.id==='group-class'?'團體教室':s.name;
const attachments={'dumbbells-pair':'雙手啞鈴','triceps-rope':'雙頭繩索','single-d-handle':'D 形單手把','stretch-mat':'伸展墊','none':'徒手','straight-bar':'直桿','ez-bar':'EZ 桿','v-handle':'V 把','ankle-strap':'腳踝帶','machine-handles':'器材握把','plate-loaded-mechanism':'槓片器材'};
const goals=[
  {id:'fullbody',name:'全身入門',english:'FULL BODY',icon:'fullbody',ids:['dumbbell-curl','dumbbell-bench-press','single-arm-cable-row','machine-leg-press','kneeling-hip-flexor-stretch']},
  {id:'arms',name:'手臂',english:'ARMS',icon:'shoulders',ids:['dumbbell-curl','rope-pushdown']},
  {id:'chest',name:'胸部',english:'CHEST',icon:'chest',ids:['dumbbell-bench-press']},
  {id:'back',name:'背部',english:'BACK',icon:'back',ids:['single-arm-cable-row']},
  {id:'legs',name:'腿部與臀部',english:'LEGS & GLUTES',icon:'legs',ids:['machine-leg-press','machine-squat-rack','machine-hip-thrust']},
  {id:'shoulders',name:'肩部',english:'SHOULDERS',icon:'shoulders',ids:['machine-shoulder-press','machine-lateral-raise']},
  {id:'stretch',name:'伸展',english:'MOBILITY',icon:'legs',ids:['kneeling-hip-flexor-stretch']},
];
function saved(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[];}catch{return [];}}
const state={trainingRoute:null,trainingProfile:loadTrainingProfile(),pendingEquipment:null,loaded:false,error:null,welcome:true,goalId:'fullbody',goal:null,mode:'guided',modal:null,closing:false,activityStage:'idle',classSegment:null,classPhase:0,course:null,catalogGroup:'all',nearby:null,active:null,info:null,activeTab:'muscles',targetId:null,targetExerciseId:null,zone:'入口與櫃台',paused:false,speed:1,overlay:true,toast:'',learned:new Set(saved('form.exercise-progress.v1').filter(exercise).map(id=>exercise(id).movementId||id)),knowledge:new Set(saved('form.learned').filter(station)),session:new Set()};
const selectedGoal=()=>goals.find(g=>g.id===state.goalId)||goals[0];
const persist=()=>{try{localStorage.setItem('form.exercise-progress.v1',JSON.stringify([...state.learned]));localStorage.setItem('form.learned',JSON.stringify([...state.knowledge]));}catch{}journal?.captureLearningState();};
function notify(message){state.toast=message;clearTimeout(toastTimer);render();toastTimer=setTimeout(()=>{state.toast='';render();},3600);}
function sync(){const available=state.loaded&&!state.welcome&&!state.modal&&!extraPanelOpen&&!mobileUI.menuOpen;world?.setEnabled(available&&!state.active&&!state.info);world?.setViewEnabled(available);mobileControls.sync();}

const catalogGroups=[['all','全部'],['dumbbells','啞鈴'],['cable','龍門架'],['mobility','草皮與伸展'],['machines','固定與槓片'],['cardio','有氧'],['classes','團課'],['recovery','設施']];
function catalogItems(){return catalogActivities.filter(e=>{const s=station(e.stationId);switch(state.catalogGroup){case 'dumbbells':return s?.type==='dumbbellCurl';case 'cable':return s?.type==='cableFly';case 'mobility':return e.category==='stretch'||s?.type==='stretchZone';case 'machines':return e.runtime==='machine'&&e.category!=='cardio';case 'cardio':return e.category==='cardio';case 'classes':return isClassActivity(e);case 'recovery':return e.runtime==='facility'&&!isClassActivity(e);default:return true;}});}
function plateLoadControl(e){if(!station(e.stationId)?.plateLoaded)return '';const load=world?.getPlateLoad(e.stationId)??10;return `<div class="plate-load-control"><div><strong>槓片重量</strong><span>每側 ${load} kg</span></div><div class="plate-load-options">${[5,10,20].map(kg=>`<button data-load="${kg}" aria-pressed="${load===kg}" class="${load===kg?'active':''}">${kg} kg／側</button>`).join('')}</div><small>只調整遊戲中的槓片配置。</small></div>`;}
function measurementMarkup(result=world?.getFacilityDiagnostics().inbody){const progress=result?.progress||0,report=result?.report;return `<h3>${report?'示範報告':'模擬量測中'}</h3><progress value="${progress}" max="1" aria-label="模擬量測進度"></progress><small>${Math.round(progress*100)}%</small>${report?`<p>固定範例，不是你的身體資料。</p><div class="measurement-values"><div><span>體重</span><strong>${report.weightKg.toFixed(1)} kg</strong></div><div><span>骨骼肌量</span><strong>${report.skeletalMuscleKg.toFixed(1)} kg</strong></div><div><span>體脂率</span><strong>${report.bodyFatPercent.toFixed(1)}%</strong></div></div>`:'<p>站穩並握住握把，螢幕會顯示示範掃描進度。</p>'}`;}
function facilityTeaching(e){return `<aside class="station-panel facility-panel" aria-label="${e.name}使用說明"><div class="station-top"><span class="eyebrow">肌動基地 / 設施</span><button class="icon-button dark" data-action="close-teaching" aria-label="離開設施">${icon('close')}</button></div><div class="station-title"><span class="station-index">${station(e.stationId)?.number||''}</span><div><small>${e.english}</small><h2>${e.name}</h2></div></div><div class="station-zone">${icon('pin')}${e.zone}<span>${e.facilityKind==='groupClass'?'團課體驗':e.facilityKind==='inbody'?'模擬量測':'互動設施'}</span></div><div class="station-scroll">${teachingReferenceMarkup(e)}<div class="facility-status"><span class="live-dot"></span><strong id="pose-label">準備使用</strong><p>拖曳滑鼠換角度，滾輪拉近或拉遠。</p></div>${e.facilityKind==='inbody'?`<div class="measurement-card" id="inbody-measurement">${measurementMarkup()}</div>`:''}${e.facilityKind==='groupClass'?'<div class="muscle-legend"><span><i class="primary-swatch"></i>活動目標</span><span><i class="secondary-swatch"></i>穩定部位</span></div>':''}<ol class="teaching-steps">${e.steps.map((step,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><h3>${step.title}</h3><p>${step.text}</p></div></li>`).join('')}</ol><p class="facility-note">${e.facilityKind==='inbody'?'畫面保留鞋服，用來示範站位；實際操作請依現場機器指示。':e.facilityKind==='groupClass'?'可以轉動視角，看看教練和學員的動作。':'這是設備互動示意，人物保留運動服。'}</p></div><div class="station-footer"><button class="primary-button full-width" data-action="close-teaching">離開設施 ${icon('arrow')}</button><p class="teaching-note">按 Esc 也可以回到走道。</p></div></aside>`;}

function header(){return `<header class="topbar"><a class="brand" href="#" data-action="home" aria-label="肌動基地 首頁"><img class="brand-symbol" src="${publicAssetUrl('brand-mark.svg')}" alt=""><span class="brand-name">肌動基地</span><small>MUSCLE BASE</small></a><div class="header-center"><span class="live-dot"></span><span id="zone-name">${state.zone}</span><span class="header-divider"></span><span>EXPLORE YOUR MOVEMENT</span></div><nav class="header-actions" aria-label="主要功能"><button class="quiet-button" data-action="journal" aria-label="訓練日誌">${icon('book')}<span>訓練日誌</span></button><button class="quiet-button" data-action="account" aria-label="${import.meta.env.VITE_ACCOUNT_MODE==='local'?'資料保存與備份':'帳號與同步'}">${icon('fullbody')}<span>${import.meta.env.VITE_ACCOUNT_MODE==='local'?'資料備份':'帳號'}</span></button><button class="icon-button" data-action="help" aria-label="操作說明">${icon('info')}</button><button class="quiet-button ${state.overlay?'overlay-on':''}" data-action="overlay" aria-pressed="${state.overlay}" title="開關 3D 人物上的肌群標色">${icon('fullbody')}<span>人物肌群</span></button><button class="quiet-button" data-action="library">${icon('book')}<span>動作清單</span></button><button class="quiet-button" data-action="training-plan">${icon('route')}<span>訓練安排</span></button><button class="quiet-button" data-action="classes">${icon('fullbody')}<span>團體課程</span></button><button class="quiet-button" data-action="coaches">${icon('fullbody')}<span>教練團隊</span></button><button class="quiet-button" data-action="map">${icon('map')}<span>場館地圖</span></button></nav></header>`;}

function welcome(){const g=selectedGoal();return `<div class="welcome-shade"></div><main class="welcome-wrap" aria-label="選擇健身房體驗"><section class="welcome-card"><div class="eyebrow"><span class="tiny-line"></span>MEET THE MOVEMENT. UNDERSTAND YOUR BODY.</div><span class="trial-pill">真人角色・全館器材</span><h1>今天想<br>練哪裡<span>？</span></h1><p class="welcome-description">選一個訓練部位，跟著推薦動作試做。<br>也可以先在健身房裡走走。</p><div class="section-heading"><span>選擇今天的訓練內容</span><small>CHOOSE YOUR EXPLORATION</small></div><div class="goal-grid">${goals.map(item=>`<button class="goal-card ${g.id===item.id?'selected':''}" data-goal="${item.id}" aria-pressed="${g.id===item.id}"><span class="goal-icon">${icon(item.icon)}</span><strong>${item.name}</strong><small>${item.english}</small><span class="goal-check">${g.id===item.id?icon('check'):''}</span></button>`).join('')}</div><div class="route-preview"><div class="route-preview-heading">${icon('route')}<strong>推薦動作</strong><span>${g.ids.length} 個動作</span></div><div class="preview-stations">${g.ids.map((id,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b>${exercise(id).name}</span>`).join('')}</div></div><button class="primary-button start-button" data-action="start" ${state.loaded?'':'disabled'}><span>${state.error?'真人角色載入失敗':state.loaded?'開始試做':'正在準備真人角色…'}</span>${icon('arrow')}</button><small id="asset-loading" class="asset-loading">${state.loaded?'角色與場館已就緒':'正在載入角色模型、骨架與貼圖'}</small><button class="free-button" data-action="free" ${state.loaded?'':'disabled'}>${icon('compass')}我想先自由走走<span>隨時從「動作清單」快速試玩 ${icon('arrow')}</span></button>${state.error?`<p class="error-message">${state.error}<button class="text-button" data-action="reload">重新載入</button></p>`:''}</section><aside class="welcome-aside"><div class="floating-tag"><span class="live-dot"></span>A CLOSER LOOK AT HOW WE MOVE.</div><h2>走近器材，<br>按 E 開始。</h2><div class="aside-divider"></div><p>紅色是主要肌群，橘色是輔助肌群。<br>上方「人物肌群」可以開關標色。</p><div class="aside-bottom"><span>啞鈴訓練</span><span>龍門架</span><span>草皮伸展</span></div></aside></main><div class="welcome-bottom"><a href="${publicAssetUrl('guide/')}" class="welcome-guide-link">器材與動作指南 ↗</a><button data-action="sources">素材與教學來源 ${icon('arrow')}</button></div>`;}

function mission(){if(state.goal?.id==='personal'&&state.trainingRoute)return personalMission();const g=state.goal,done=g?g.ids.filter(id=>state.session.has(id)).length:0;return `<aside class="mission-panel glass-panel"><div class="panel-overline">MOVEMENT EXPLORATION<span class="panel-badge">${g?'引導模式':'自由探索'}</span></div><h2>${g?g.name+'探索':'自由走動'}</h2><p class="mission-description">${g?'點動作可顯示路線；按「快速試玩」可直接開始。':'靠近器材按 E 使用；啞鈴、龍門架、草皮和團體教室可以選內容。'}</p>${g?.plan?`<p class="mission-personal-note">約 ${g.plan.totalMinutes} 分鐘・${g.plan.volumeLabel}<br>下方是動作學習進度，不是實際運動紀錄。</p><button class="text-button" data-action="training-plan">調整訓練安排 →</button>`:''}${g?`<div class="mission-progress"><span style="width:${done/g.ids.length*100}%"></span></div><div class="progress-caption"><span>${done===g.ids.length?'這次探索已完成 ✓':'這次已了解'}</span><b>${done} / ${g.ids.length}</b></div><ol class="mission-list">${g.ids.map((id,i)=>{const e=exercise(id);return `<li><button class="mission-item ${state.targetExerciseId===id?'target':''} ${state.session.has(id)?'done':''}" data-target-exercise="${id}"><span class="mission-number">${state.session.has(id)?icon('check'):String(i+1).padStart(2,'0')}</span><span><strong>${e.name}</strong><small>${g.plan?.steps.find(s=>s.id===id)?.prescription||title(station(e.stationId))}</small></span>${icon('pin')}</button></li>`;}).join('')}</ol>${state.targetExerciseId?`<button class="secondary-button full-width" data-demo="${state.targetExerciseId}">${icon('play')}快速試玩這個動作</button>`:''}`:`<div class="free-stat"><strong>${state.learned.size}<small>/ ${catalogActivities.filter(e=>e.runtime!=='facility'||isClassActivity(e)).length}</small></strong><span>已了解的動作</span></div><button class="secondary-button full-width" data-action="library">${icon('book')}查看動作清單</button>`}<button class="text-button switch-mode" data-action="home">重新選擇探索內容 ${icon('arrow')}</button></aside>`;}

function teaching(){const selected=state.active||state.info,e=selected?(exercise(selected.id)||selected):null;if(!e)return '';if(isClassActivity(e))return classTeaching(e);if(e.runtime==='facility')return facilityTeaching(e);const demo=!!state.active,stretch=e.category==='stretch',mobility=e.category==='mobility';return `<aside class="station-panel" aria-label="${e.name}教學"><div class="station-top"><span class="eyebrow">${demo?'UNDERSTAND YOUR MOVEMENT':'MEET THE EQUIPMENT'}</span><button class="icon-button dark" data-action="close-teaching" aria-label="關閉教學">${icon('close')}</button></div><div class="station-title"><span class="station-index">${demo?String(catalogActivities.findIndex(item=>item.movementId===e.movementId)+1).padStart(2,'0'):e.number}</span><div><small>${e.english}</small><h2>${e.name}</h2></div></div><div class="station-zone">${icon('pin')}${demo?title(station(e.stationId)):e.zone}<span>${demo?(stretch?'伸展':e.setupLabel||attachments[e.attachmentId]||'動作示範'):'器材介紹'}</span></div><div class="station-scroll">${teachingReferenceMarkup(e)}${mocapNotice(e.id)}${personalRouteTeaching(e)}${plateLoadControl(e)}${equipmentControls(e)}<div class="teaching-tabs" role="tablist" aria-label="教學內容">${[['muscles',stretch?'伸展哪裡':'練哪裡'],['technique','怎麼做'],['range','動作行程']].map(([id,label])=>`<button data-tab="${id}" class="${state.activeTab===id?'active':''}" role="tab" aria-selected="${state.activeTab===id}">${label}</button>`).join('')}</div><div class="teaching-content" data-content="muscles"><div class="muscle-visual">${muscleMap(e.muscleKeys,e.secondaryMuscleKeys)}<div class="muscle-legend"><span><i class="primary-swatch"></i>${mobility?'活動目標':stretch?'伸展目標':'主要肌群'}</span><span><i class="secondary-swatch"></i>${stretch?'支撐參與':'輔助肌群'}</span></div></div><div class="muscle-label"><small>${mobility?'主要活動部位':stretch?'主要伸展目標':'主要訓練'}</small><strong>${e.primary.join('、')}</strong></div><div class="muscle-label secondary"><small>${stretch?'支撐與穩定':'輔助參與'}</small><span>${e.secondary.join('、')||'依動作設定而異'}</span></div><p class="activation-note">${mobility?'紅色表示這個動作的活動部位，不表示出力大小。':stretch?'紅色表示被伸展的部位，不表示出力大小。':'標色表示動作參與部位，不代表量測的出力強度。'}</p></div><div class="teaching-content" data-content="technique">${e.facilityKind==='inbody'?`<div class="measurement-card" id="inbody-measurement">${measurementMarkup()}</div>`:''}${e.facilityKind==='groupClass'?'<div class="muscle-legend"><span><i class="primary-swatch"></i>活動目標</span><span><i class="secondary-swatch"></i>穩定部位</span></div>':''}<ol class="teaching-steps">${e.steps.map((step,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><h3>${step.title}</h3><p>${step.text}</p></div></li>`).join('')}</ol><div class="coach-tip"><strong>常見錯誤</strong><ul>${e.mistakes.map(text=>`<li>${text}</li>`).join('')}</ul></div></div><div class="teaching-content" data-content="range"><div class="range-stops"><div><b>A</b><small>起始位置</small><p>${e.range.start}</p></div><span>↓</span><div><b>B</b><small>${stretch?'伸展位置':'結束位置'}</small><p>${e.range.end}</p></div></div><div class="coach-tip"><strong>動作提醒</strong><p>${e.range.cue}</p></div></div></div><div class="station-controls">${demo?`<div class="activity-flow"><span>就位・入座・拿取</span><i>→</i><span>運動</span><i>→</i><span>放回・離開</span><strong id="activity-flow-status">走向器材</strong></div><div class="animation-control"><div class="animation-heading"><span><i class="live-dot"></i><strong>3D 動作示範</strong></span><span id="pose-label">準備姿勢</span></div><progress id="pose-progress" max="1" value="0" aria-label="動作進度"></progress><div class="animation-buttons"><button data-action="pause" ${state.activityStage==='exercising'?'':'disabled'} class="play-control" aria-label="${state.paused?'播放示範':'暫停示範'}">${icon(state.paused?'play':'pause')}<span>${state.paused?'播放':'暫停'}</span></button><div class="speed-controls">${[.5,1].map(speed=>`<button data-speed="${speed}" class="${state.speed===speed?'active':''}" aria-pressed="${state.speed===speed}">${speed===.5?'0.5× 慢速':'1× 正常'}</button>`).join('')}</div></div><div class="trial-pose-tools"><label>逐格觀察<input type="range" ${state.activityStage==='exercising'?'':'disabled'} id="pose-scrub" min="0" max="1" step="0.005" value="0" aria-label="調整動作行程"></label><button class="text-button" data-action="restart">${icon('reset')}從頭觀看</button></div></div>`:`<div class="coach-tip"><p>可從動作清單挑選示範，也可以前往啞鈴區、龍門架與草皮，選擇想認識的動作。</p><button class="text-button" data-action="library">查看動作清單 ${icon('arrow')}</button></div>`}</div><div class="station-footer"><button class="primary-button full-width" data-action="learned" ${state.activityStage==='exercising'?'':'disabled'}>${icon('check')}${demo?'已了解這個動作':'已認識這台器材'}${icon('arrow')}</button><p class="teaching-note">${demo?'示範活動範圍需依個人與器材調整。':'器材教學參考。'}${e.id==='dumbbell-shoulder-press'?'肩推採真人動捕的節奏參考，手腳仍沿用校正路徑。':e.id==='dumbbell-goblet-squat'?'深蹲節奏參考徒手動捕，再改編到持鈴路徑；不是持鈴拍攝。':''}<a href="${e.source.url}" target="_blank" rel="noopener noreferrer">資料來源 ↗</a></p></div></aside>`;}

function hud(){const e=exercise(state.targetExerciseId),target=station(state.targetId),active=state.active||state.info;return `<main class="explore-ui" aria-label="健身房探索">${active?'':mission()}${!active&&target?`<div class="navigation-pill"><span class="navigation-icon">${icon('pin')}</span><span>正在前往<strong>${e?.name||title(target)}</strong></span><b id="target-distance">— m</b></div>`:''}${state.active&&(state.active.runtime!=='facility'||isClassActivity(state.active))?`<div class="demo-badge glass-panel"><span class="live-dot"></span><div><strong>拖曳換角度，也可以暫停看細節</strong><small>拖曳轉動視角・滾輪拉近・可暫停逐格觀察</small><div class="muscle-legend"><span><i class="primary-swatch"></i>${isClassActivity(state.active)?(classActivationLabel(classLesson(state.active),state.classSegment||classBlockAt(classLesson(state.active),state.classPhase))):state.active.category==='mobility'?'活動目標':state.active.category==='stretch'?'伸展目標':'主要肌群'}</span><span><i class="secondary-swatch"></i>${isClassActivity(state.active)?'輔助與支撐':state.active.category==='stretch'?'支撐參與':'輔助肌群'}</span></div></div></div>`:''}${teaching()}${!active?`<button class="minimap-card glass-panel" data-action="map" aria-label="開啟場館地圖"><div class="minimap-heading"><span>${icon('map')}場館導覽</span><small>點擊展開 ↗</small></div>${mapMarkup(stations,state.targetId,state.knowledge)}</button>`:''}${!active&&state.nearby?`<button class="interaction-prompt" data-action="interact"><kbd>E</kbd><span><small>${world?.getOccupancy(state.nearby.id).state==='exercising'?'有人使用・按 E 接手':state.nearby.type==='facility'?'使用設施':activitiesForStation(state.nearby.id).length>1?'選擇這裡的動作':'使用這台器材'}</small><strong>${title(state.nearby)}</strong></span>${icon('arrow')}</button>`:''}<div class="controls-bar"><span><kbd>W</kbd><span class="stacked-keys"><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd></span>移動</span><span><kbd>Shift</kbd>奔跑</span><i></i><span><span class="mouse-icon"></span>拖曳觀察</span><i></i><span>滾輪縮放</span><i></i><span><kbd>${active?'Esc':'E'}</kbd>${active?'返回探索':'選擇動作'}</span><button data-action="help" aria-label="操作說明">${icon('info')}</button></div></main>`;}

function exerciseCards(items){return items.map((e,i)=>isClassActivity(e)?classCards([e]):`<article class="trial-exercise-card"><div class="catalog-item-top"><b>${String(catalogActivities.findIndex(item=>item.movementId===e.movementId)+1).padStart(2,'0')}</b><span class="catalog-type">${e.category==='stretch'?'伸展':attachments[e.attachmentId]||e.setupLabel||'重量訓練'}</span></div><h3>${e.name}</h3><small>${e.english}</small><p>${e.primary.join('・')}</p><span class="trial-location">${icon('pin')}${title(station(e.stationId))}</span><div class="trial-card-actions"><button class="primary-button" data-demo="${e.id}">${icon('play')}快速試玩</button><button class="secondary-button" data-target-exercise="${e.id}">${icon('route')}導航</button></div></article>`).join('');}
function modal(){if(!state.modal)return '';let content,caption;if(state.modal==='training-plan'){caption='今天的訓練安排';content=trainingPlanMarkup(state.trainingProfile,exercise,state.loaded);}else if(state.modal==='coaches'){caption='教練團隊';content=coachesMarkup(world?.getCoachRoster()||[]);}else if(state.modal==='map'){caption='場館地圖';content=`<p class="modal-description">點選器材或設施的編號，就會顯示前往路線。各區使用不同的底色。</p><div class="large-map-wrap">${mapMarkup(stations,state.targetId,state.knowledge,true)}</div>`;}else if(['library','actions','classes'].includes(state.modal)){const classMenu=state.modal==='classes'||state.modal==='actions'&&state.nearby?.id==='group-class';const items=classMenu?groupClassDefinitions.map(e=>exercise(e.id)||e):state.modal==='actions'?activitiesForStation(state.nearby?.id):catalogItems();caption=classMenu?'團體課程':state.modal==='actions'?title(state.nearby):'動作與設施清單';content=`<p class="modal-description">${classMenu?'選一堂課，人物會到教室就位，教練和學員也會換成同一套示範。每堂都有分段流程，可暫停、慢放或查看指定段落。':state.modal==='actions'?'選好動作後，器材會換成對應的設定與握把。':'可快速開始示範，或導航到訓練點後按 E 選擇動作。'}</p>${state.modal==='library'?`<div class="activity-filters" aria-label="篩選動作">${catalogGroups.map(([id,name])=>`<button data-catalog-group="${id}" aria-pressed="${state.catalogGroup===id}" class="${state.catalogGroup===id?'active':''}">${name}</button>`).join('')}</div>`:''}<div class="catalog-result-caption">${items.length} 個項目</div><div class="trial-exercise-grid">${exerciseCards(items)}</div>`;}else if(state.modal==='sources'){caption='素材與教學來源';content=`<div class="source-list">${catalogActivities.filter(e=>e.source?.url).map(e=>`<a href="${e.source.url}" target="_blank" rel="noopener noreferrer"><strong>${e.name} ↗</strong><p>${e.source.label}</p></a>`).join('')}${facilitySources.slice(0,3).map(source=>`<a href="${source.url}" target="_blank" rel="noopener noreferrer"><strong>${source.label} ↗</strong><p>${source.note}</p></a>`).join('')}<a href="${publicAssetUrl('models/athlete/credits.json')}" target="_blank" rel="noopener noreferrer"><strong>人物模型與素材授權 ↗</strong><p>查看這次真人角色使用的資產與來源紀錄。</p></a></div>${motionCreditsMarkup()}`;}else{caption='操作與探索';content=`<div class="help-grid"><div><kbd>W A S D</kbd><strong>在健身房中走動</strong><p>也可用方向鍵移動，按住 Shift 奔跑。</p></div><div><kbd>E</kbd><strong>靠近訓練點選擇動作</strong><p>普通器材直接開始示範；啞鈴、龍門架、草皮和團體教室會先列出可選內容。有人使用時，對方會先離開。</p></div><div><kbd>滑鼠</kbd><strong>轉個角度觀察</strong><p>按住場景拖曳轉動，滾輪拉近或拉遠。</p></div><div><kbd>Esc</kbd><strong>返回探索或關閉視窗</strong><p>M 開啟地圖；上方可切換人物肌群標色。</p></div></div><p class="help-note">紅色：主要訓練肌群，或伸展動作的目標部位。橘色：輔助／支撐參與。標色並非量測到的肌肉出力。</p><div class="help-footer"><a class="text-button" href="${publicAssetUrl('guide/')}">器材與動作指南 ↗</a><a class="text-button" href="${publicAssetUrl('about/')}">認識肌動基地 ↗</a><button class="text-button" data-action="motion-review">動作檢查與問題紀錄</button><button class="text-button" data-action="sources">素材與教學來源 ${icon('arrow')}</button><button class="text-button subtle" data-action="reset-progress">重設動作學習進度</button></div>`;}return `<div class="modal-overlay" data-backdrop><section class="modal-card ${state.modal==='map'?'map-modal':(['library','coaches','classes','training-plan'].includes(state.modal)||state.modal==='actions'&&state.nearby?.id==='group-class')?'trial-library-modal':''}" role="dialog" aria-modal="true" aria-label="${caption}"><div class="modal-heading"><div><span class="eyebrow">肌動基地 / 動作探索</span><h2>${caption}</h2></div><button class="icon-button dark" data-action="close-modal" aria-label="關閉視窗">${icon('close')}</button></div>${content}${state.modal==='help'?graphicsSettings():''}</section></div>`;}

function graphicsSettings(){const quality=world?.getPerformanceDiagnostics?.();return `<section class="graphics-settings"><label for="graphics-quality">畫質<select id="graphics-quality" aria-label="畫質">${[['auto','自動調整'],['flow','流暢優先'],['clear','畫面細節']].map(([value,label])=>`<option value="${value}" ${(quality?.preference||'auto')===value?'selected':''}>${label}</option>`).join('')}</select></label><p>覺得卡頓時可選「流暢優先」，會降低解析度並關閉動態陰影。手機也會縮短遠景距離；選「畫面細節」可恢復完整遠景。畫質設定會自動保存。</p>${quality?.preference==='auto'&&quality?.active==='flow'?'<p>目前為了維持操作流暢，已自動降低解析度並關閉陰影。人物動作、手腳接點與肌群標色保留；可手動選畫面細節。</p>':''}</section>${performanceUI.markup()}`;}
function render(){classBlockDomKey=null;classScrubGesture=null;activityDom.reset();app.innerHTML=`<div id="scene-fade"></div>${header()}${state.welcome?welcome():hud()}${modal()}${state.toast?`<div class="toast" role="status">${icon('check')}${state.toast}</div>`:''}`;classPanelNode=app.querySelector('.class-panel');document.body.classList.toggle('is-welcome',state.welcome);document.body.classList.toggle('is-teaching',!!state.active||!!state.info);courseSound.repaint();document.querySelectorAll('[data-content]').forEach(el=>el.classList.toggle('hidden',el.dataset.content!==state.activeTab));mobileUI.decorate();sync();}
function targetExercise(id){const e=exercise(id);if(!e)return;state.targetExerciseId=id;state.targetId=e.stationId;world?.setTarget(e.stationId);}
function closeTeaching(){state.pendingEquipment=null;if(state.active){state.closing=true;world?.stopExercise();}else if(state.info){world?.setMuscleHighlights([],[]);state.info=null;}state.paused=false;render();}
function openExercise(id){state.pendingEquipment=null;const e=exercise(id);if(!state.loaded||!e)return;state.modal=null;if(!world.startExercise(id)){notify('目前無法走到器材前，請先移到走道再試一次。');return;}state.welcome=false;state.info=null;const current=world.getActivityState();state.active=exercise(current.exerciseId)||e;state.closing=current.exerciseId!==id;state.activeTab='muscles';state.classSegment=null;state.classPhase=0;state.course=null;state.paused=false;state.speed=1;world.setMuscleOverlayEnabled(state.overlay);world.setAnimationSpeed(1);world.setAnimationPaused(false);render();}
function openStation(s){if(!s)return;const matches=activitiesForStation(s.id);if(matches.length===1){openExercise(matches[0].id);return;}if(matches.length){state.nearby=s;state.modal='actions';render();}else{notify('這裡目前沒有可使用的動作。');}}
function openModal(name){if(name!=='help'&&(state.active||state.info))closeTeaching();state.modal=name;render();}
function begin(free=false){if(!state.loaded)return;state.welcome=false;state.trainingRoute=null;state.goal=free?null:selectedGoal();state.mode=free?'free':'guided';state.session=new Set();state.modal=null;if(state.goal){targetExercise(state.goal.ids[0]);openExercise(state.goal.ids[0]);}else{state.targetId=null;state.targetExerciseId=null;world.setTarget(null);render();}}

app.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-goal],[data-demo],[data-target-exercise],[data-map-station],[data-speed],[data-tab],[data-catalog-group],[data-load],[data-class-phase],[data-route-step],[data-backdrop]');if(!el)return;if(el.dataset.routeStep){if(!targetPersonalRouteStep(el.dataset.routeStep))return;if(el.dataset.demo)openExercise(el.dataset.demo);else render();return;}if(el.hasAttribute('data-class-phase')){if(!['exercising','completed'].includes(state.activityStage))return;state.paused=true;world.setAnimationPaused(true);world.seekExercise(Number(el.dataset.classPhase));render();return;}if(el.dataset.catalogGroup){state.catalogGroup=el.dataset.catalogGroup;render();return;}if(el.dataset.load&&state.active){queueEquipmentSetting(state.active.id,{plateLoadKg:Number(el.dataset.load)});return;}const {action,goal,demo,targetExercise:targetId,mapStation,speed,tab}=el.dataset;if(goal){state.goalId=goal;render();return;}if(demo){if(state.welcome){state.goal=null;state.mode='free';}openExercise(demo);return;}if(targetId||mapStation){if(state.welcome){state.welcome=false;state.goal=null;state.mode='free';}state.modal=null;if(state.active||state.info)closeTeaching();if(targetId)targetExercise(targetId);else{state.targetId=mapStation;state.targetExerciseId=exercises.find(e=>e.stationId===mapStation)?.id||null;world.setTarget(mapStation);}render();return;}if(speed){state.speed=Number(speed);world.setAnimationSpeed(state.speed);document.querySelectorAll('[data-speed]').forEach(button=>{const active=button===el;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});return;}if(tab){state.activeTab=tab;document.querySelectorAll('[data-tab]').forEach(button=>{button.classList.toggle('active',button===el);button.setAttribute('aria-selected',String(button===el));});document.querySelectorAll('[data-content]').forEach(section=>section.classList.toggle('hidden',section.dataset.content!==tab));return;}if(el.hasAttribute('data-backdrop')){if(event.target===el){state.modal=null;render();}return;}switch(action){case 'journal':journal?.open({exerciseId:state.active?.id});break;case 'account':journal?.openAccount();break;case 'motion-review':review?.open();break;case 'apply-equipment-adjustments':{const fields=[...app.querySelectorAll('[data-equipment-adjustment]')];if(state.active&&fields.every(field=>field.reportValidity()))queueEquipmentSetting(state.active.id,Object.fromEntries(fields.map(field=>[field.dataset.equipmentAdjustment,Number(field.value)])));break;}case 'home':event.preventDefault();if(state.active||state.info)closeTeaching();state.modal=null;state.welcome=true;render();break;case 'apply-bench-angle':{const input=app.querySelector('[data-bench-angle]');if(input&&state.active&&!state.pendingEquipment)queueEquipmentSetting(state.active.id,{benchAngle:Number(input.value)});break;}case 'training-plan':openModal('training-plan');break;case 'start-training-plan':beginPersonalPlan();break;case 'restart-training-route':beginPersonalPlan(state.goal?.plan);break;case 'start':begin();break;case 'free':begin(true);break;case 'library':openModal('library');break;case 'coaches':openModal('coaches');break;case 'classes':openModal('classes');break;case 'map':openModal('map');break;case 'help':openModal('help');break;case 'sources':openModal('sources');break;case 'close-modal':state.modal=null;render();break;case 'course-leave':case 'close-teaching':closeTeaching();break;case 'interact':openStation(state.nearby);break;case 'overlay':state.overlay=!state.overlay;world?.setMuscleOverlayEnabled(state.overlay);el.setAttribute('aria-pressed',String(state.overlay));el.classList.toggle('overlay-on',state.overlay);break;case 'pause':state.paused=!state.paused;world.setAnimationPaused(state.paused);el.innerHTML=`${icon(state.paused?'play':'pause')}<span>${state.paused?'播放':'暫停'}</span>`;el.setAttribute('aria-label',state.paused?'播放示範':'暫停示範');break;case 'course-restart':case 'restart':if(isClassActivity(state.active)){state.course=null;state.classPhase=0;state.classSegment=null;world.restartCourse();}else world.seekExercise(0);state.paused=false;world.setAnimationPaused(false);render();break;case 'learned':{if(state.active){const e=state.active;state.learned.add(e.movementId||e.id);state.session.add(e.movementId||e.id);state.knowledge.add(e.stationId);persist();closeTeaching();if(state.goal?.id==='personal'&&state.trainingRoute){finishPersonalRouteStep(e);break;}const next=state.goal?.ids.find(id=>!state.session.has(id));if(next)targetExercise(next);else{state.targetId=null;state.targetExerciseId=null;world.setTarget(null);}notify(next?`已了解，下一個動作是${exercise(next).name}。`:'這次探索已完成，也可以繼續自由走走。');}else if(state.info){state.knowledge.add(state.info.id);persist();closeTeaching();}break;}case 'reset-progress':state.learned.clear();state.session.clear();persist();state.modal=null;notify('動作學習進度已重設');break;case 'reload':location.reload();break;}});
app.addEventListener('pointerdown',event=>{if(event.target.id==='pose-scrub'&&!event.target.disabled&&hasCurrentClassPanel(state.active?.id))classScrubGesture={id:event.pointerId,panel:classPanelNode};},true);
const endClassScrub=event=>{if(classScrubGesture&&((event.type==='blur'&&event.target===window)||(event.type!=='blur'&&event.pointerId===classScrubGesture.id)))classScrubGesture=null;};
for(const type of ['pointerup','pointercancel','lostpointercapture','blur'])window.addEventListener(type,endClassScrub,true);
app.addEventListener('input',event=>{if(event.target.id!=='pose-scrub'||!state.active||!['exercising','completed'].includes(state.activityStage))return;const phase=Number(event.target.value);state.paused=true;world.setAnimationPaused(true);world.seekExercise(phase);const button=document.querySelector('[data-action="pause"]');if(button){button.innerHTML=`${icon('play')}<span>播放</span>`;button.setAttribute('aria-label','播放示範');}});
window.addEventListener('keydown',event=>{if(extraPanelOpen)return;if(event.key==='Escape'){event.preventDefault();if(state.modal){state.modal=null;render();}else if(state.active||state.info)closeTeaching();return;}if(event.target instanceof HTMLElement&&event.target.closest('input,textarea,select,[contenteditable="true"]'))return;if(event.repeat||event.ctrlKey||event.metaKey||event.altKey)return;if(event.key.toLowerCase()==='e'&&!state.welcome&&!state.modal&&!state.active&&!state.info){event.preventDefault();openStation(state.nearby);}if(event.key.toLowerCase()==='m'&&!state.welcome&&!state.active){event.preventDefault();if(state.modal==='map'){state.modal=null;render();}else openModal('map');}});
app.addEventListener('change',event=>{const e=event.target;if(e.dataset.planField){const field=e.dataset.planField;state.trainingProfile=saveTrainingProfile({...state.trainingProfile,[field]:e.value,...(field==='minutes'?{}:{volumeStep:0})});journal?.captureLearningState();render();return;}if(e.hasAttribute('data-bench-angle')){previewBenchAngle(e);return;}if(e.hasAttribute('data-handle-option')&&state.active){const option=equipmentOptionsFor(state.active.id).handleOptions.find(o=>o.value===e.value);if(option?.settings)queueEquipmentSetting(state.active.id,option.settings);else if(option)openExercise(option.exerciseId);return;}if(event.target.id==='graphics-quality')world?.setGraphicsQuality(event.target.value);});
app.addEventListener('keydown',event=>{const el=event.target.closest('[data-map-station]');if(el&&(event.key==='Enter'||event.key===' ')){event.preventDefault();el.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});


function personalMission(){
 const g=state.goal,route=state.trainingRoute,progress=trainingRouteProgress(route),current=progress.current,viewed=new Set(route.completedKeys);
 return `<aside class="mission-panel glass-panel personal-route-panel"><div class="panel-overline">MOVEMENT EXPLORATION<span class="panel-badge">分段探索</span></div><h2>${g.name}探索</h2><p class="mission-description">依序查看暖身、主要內容與緩和。同一台器材可能會再訪，可以點選步驟換路線。</p><p class="mission-personal-note">約 ${g.plan.totalMinutes} 分鐘・${g.plan.volumeLabel}<br>下方記錄已看過的探索步驟，不是實際運動紀錄。</p><button class="text-button" data-action="training-plan">調整訓練安排 →</button><div class="mission-progress"><span style="width:${progress.done/Math.max(1,progress.total)*100}%"></span></div><div class="progress-caption"><span>${progress.complete?'這份安排已探索完 ✓':'已看過的步驟'}</span><b>${progress.done} / ${progress.total}</b></div><ol class="mission-list">${route.steps.map((step,index)=>{const e=exercise(step.id),selected=current?.key===step.key,done=viewed.has(step.key);return `<li><button class="mission-item ${selected?'target':''} ${done?'done':''}" data-route-step="${step.key}" ${selected?'aria-current="step"':''} aria-label="${step.label}：${e.name}"><span class="mission-number">${done?icon('check'):String(index+1).padStart(2,'0')}</span><span><strong>${step.label}・${e.name}</strong><small>${step.prescription}</small></span>${icon('pin')}</button></li>`;}).join('')}</ol>${current?`<button class="secondary-button full-width" data-demo="${current.id}" data-route-step="${current.key}">${icon('play')}快速試玩這個步驟</button>`:''}${progress.complete?'<button class="secondary-button full-width" data-action="restart-training-route">重新探索這份安排</button>':''}<button class="text-button switch-mode" data-action="home">重新選擇探索內容 ${icon('arrow')}</button></aside>`;
}
function personalRouteTeaching(e){
 if(state.goal?.id!=='personal')return '';
 const step=currentTrainingRouteStep(state.trainingRoute);if(!trainingStepMatchesActivity(step,e))return '';
  return `<details class="coach-tip training-step-context" aria-label="目前探索步驟" data-route-context="${step.key}"><summary><strong>${step.label}・第 ${step.index+1} 步</strong><span>${step.prescription}</span></summary><p>${step.cue}</p><p>按「已了解」只記錄看過這個步驟，不表示已實際完成運動。</p></details>`;
}
function targetPersonalRouteStep(key){
 if(state.goal?.id!=='personal'||!state.trainingRoute?.steps.some(step=>step.key===key))return false;
 state.trainingRoute=selectTrainingRouteStep(state.trainingRoute,key);const step=currentTrainingRouteStep(state.trainingRoute);targetExercise(step.id);return true;
}
function finishPersonalRouteStep(activity){
 const result=acknowledgeTrainingRouteStep(state.trainingRoute,activity);state.trainingRoute=result.route;
 if(result.nextStep)targetExercise(result.nextStep.id);else{state.targetId=null;state.targetExerciseId=null;world.setTarget(null);}
 if(!result.acknowledged){notify(result.nextStep?`已了解這個動作。這份安排接著是${result.nextStep.label}：${exercise(result.nextStep.id).name}。`:'已了解這個動作，這份安排的探索步驟已看完。');return;}
 notify(result.complete?'這份安排已探索完；記錄的是看過示範，沒有計算實際運動。':`已看過這個步驟，接著是${result.nextStep.label}：${exercise(result.nextStep.id).name}。`);
}

function equipmentControls(e){
 const options=world?.getEquipmentOptions?.(e.id)||equipmentOptionsFor(e.id),settings=world?.getEquipmentSettings?.(e.id)||{},pending=!!state.pendingEquipment;
 if(!options.benchAngles.length&&!options.handleOptions.length&&!options.adjustments?.length)return '';
 const selectedHandle=options.handleOptions.find(o=>o.settings?Object.entries(o.settings).every(([k,v])=>settings[k]===v):o.exerciseId===e.id)?.value;
 const draftAngle=state.pendingEquipment?.id===e.id?state.pendingEquipment.settings.benchAngle??settings.benchAngle:settings.benchAngle;
 const adjustmentControl=options.adjustments?.length?`<div class="equipment-adjustment-grid">${options.adjustments.map(option=>`<label>${option.label}<span class="adjustment-unit">${option.unit}</span><input data-equipment-adjustment="${option.key}" aria-label="${option.label}" type="number" min="${option.min}" max="${option.max}" step="${option.step}" value="${settings[option.key]??option.defaultValue}" ${pending?'disabled':''}><small>${option.help||''}</small></label>`).join('')}</div><button class="secondary-button full-width" data-action="apply-equipment-adjustments" ${pending?'disabled':''}>放回器材並套用設定</button>`:'';
 const benchControl=options.benchAngles.length?`<div class="bench-angle-controls"><label>椅背角度<select data-bench-angle aria-label="椅背角度" ${pending?'disabled':''}>${options.benchAngles.map(o=>`<option value="${o.value}" ${draftAngle===o.value?'selected':''}>${o.label}</option>`).join('')}</select></label><label>拖曳調整椅背角度 <output data-bench-angle-output>${draftAngle}°</output><input data-bench-angle-slider aria-label="拖曳調整椅背角度" type="range" min="${options.benchAngleRange.min}" max="${options.benchAngleRange.max}" step="${options.benchAngleRange.step}" value="${draftAngle}" ${pending?'disabled':''}></label><button class="primary-button full-width bench-angle-apply" data-action="apply-bench-angle" disabled>套用 ${draftAngle}°</button></div>`:'';
 return `<details class="equipment-settings" aria-label="器材設定" ${pending?'open':''}><summary>器材設定<small>${options.benchAngles.find(o=>o.value===settings.benchAngle)?.label||options.handleOptions.find(o=>o.value===selectedHandle)?.label||'更換設定'}</small></summary>${benchControl}${adjustmentControl}${options.handleOptions.length?`<label>握把與相容動作<select data-handle-option aria-label="握把與相容動作" ${pending?'disabled':''}>${options.handleOptions.map(o=>`<option value="${o.value}" ${selectedHandle===o.value?'selected':''}>${o.label}</option>`).join('')}</select></label>`:''}<p>${pending?'正在收回器材，完成後會換設定並重新就位。':options.benchAngles.length?'選好角度後按套用，人物會先放回啞鈴，調好椅背再重新就位。':'換設定時會先放回器材，再重新就位。選單只列出已校正的組合。'}</p></details>`;
}
function previewBenchAngle(input){
 if(!state.active||state.pendingEquipment)return;
 const angle=Number(input.value),options=equipmentOptionsFor(state.active.id);
 if(!options.benchAngles.some(item=>item.value===angle))return;
 const panel=input.closest('.bench-angle-controls');if(!panel)return;
 panel.querySelector('[data-bench-angle]').value=String(angle);
 panel.querySelector('[data-bench-angle-slider]').value=String(angle);
 panel.querySelector('[data-bench-angle-output]').textContent=`${angle}°`;
 const button=panel.querySelector('[data-action="apply-bench-angle"]');button.textContent=`套用 ${angle}°`;button.disabled=angle===world.getEquipmentSettings(state.active.id).benchAngle;
}
app.addEventListener('input',event=>{if(event.target.hasAttribute('data-bench-angle-slider'))previewBenchAngle(event.target);});
function applyEquipmentSetting(pending){state.pendingEquipment=null;const result=world.setEquipmentSettings(pending.id,pending.settings);if(result.ok)openExercise(pending.id);else notify(result.reason||'這個設定目前無法使用。');}
function queueEquipmentSetting(id,settings){const pending={id,settings};state.pendingEquipment=pending;if(world.getActivityState().exerciseId){world.stopExercise();render();}else applyEquipmentSetting(pending);}
function beginPersonalPlan(recipe){if(!state.loaded)return;const plan=recipe?.steps?recipe:createTrainingPlan(state.trainingProfile);state.welcome=false;state.goal={id:'personal',name:plan.title,ids:plan.ids,plan};state.trainingRoute=createTrainingRoute(plan);state.mode='guided';state.session=new Set();state.modal=null;state.pendingEquipment=null;const first=currentTrainingRouteStep(state.trainingRoute);if(first){targetExercise(first.id);openExercise(first.id);}else render();}
app.addEventListener('click',event=>{const button=event.target.closest('[data-plan-feedback]');if(!button)return;state.trainingProfile=saveTrainingProfile(adjustTrainingProfile(state.trainingProfile,button.dataset.planFeedback));journal?.captureLearningState();render();});

journal=createTrainingJournal({getCatalog:()=>catalogActivities,getProgress:()=>({learned:[...state.learned],knowledge:[...state.knowledge]}),getProfile:()=>state.trainingProfile,onRemoteState(snapshot){state.learned=new Set((snapshot.learned||[]).filter(exercise));state.knowledge=new Set((snapshot.knowledge||[]).filter(station));state.trainingProfile=saveTrainingProfile(snapshot.profile||{});persist();render();},onOpenChange(open){extraPanelOpen=open;sync();},notify});
review=createMotionReview({getCatalog:()=>catalogActivities,getWorld:()=>world,onOpenChange(open){extraPanelOpen=open;sync();}});

render();
try{
  world=await createWorld({canvas:document.querySelector('#gym-canvas'),stations,onNearbyChange(s){if(s?.id!==state.nearby?.id){state.nearby=s;if(!state.welcome&&!state.active&&!state.info&&!state.modal)render();}},onZoneChange(zone){state.zone=zone;const el=document.querySelector('#zone-name');if(el)el.textContent=zone;},onActivityChange(event){state.activityStage=event.status;if(!['counting-in','exercising','completed'].includes(event.status))courseSound.stop();if(event.status==='finished'){if(state.active?.id===event.id)state.active=null;state.closing=false;state.paused=false;}else if(event.status==='approaching'){state.active=exercise(event.id);state.closing=false;}if(event.status==='finished'&&state.pendingEquipment){const pending=state.pendingEquipment;queueMicrotask(()=>{if(state.pendingEquipment===pending&&!world.getActivityState().exerciseId)applyEquipmentSetting(pending);});}if(state.loaded&&!(['exercising','completed'].includes(event.status)&&hasCurrentClassPanel(event.id)))render();},onPoseProgress({phase,label,stage,classSegment=null,course=null}){const courseStateChanged=!!state.course?.complete!==!!course?.complete||!!state.course?.previewed!==!!course?.previewed;state.activityStage=stage;state.classPhase=phase;state.classSegment=classSegment;state.course=course;if(isClassActivity(state.active)){const current=world.getActivityState();courseSound.update({id:state.active.id,kind:state.active.classKind||'warmup',elapsed:course?.elapsed||0,duration:course?.duration||state.active.duration,stage,paused:current.paused,speed:current.speed,segment:classSegment,previewed:course?.previewed,countInRemaining:course?.countInRemaining});}if(isClassActivity(state.active)&&courseStateChanged&&!hasCurrentClassPanel(state.active.id))render();updateClassProgress(phase,classSegment,label);activityDom.update({stage,isClass:isClassActivity(state.active),phase,label,measurementMarkup});},onAssetProgress(message){const el=document.querySelector('#asset-loading');if(el)el.textContent=typeof message==='string'?message:'正在載入真人角色與貼圖…';},onTransition(opacity){const el=document.querySelector('#scene-fade');if(el)el.style.opacity=String(opacity);}});
  state.loaded=true;lastTime=performance.now();render();
  const requestedExercise=new URLSearchParams(location.search).get('exercise');
  if(requestedExercise&&catalogActivities.some(item=>item.id===requestedExercise)){state.welcome=false;state.mode='free';openExercise(requestedExercise);}
  if(import.meta.env.DEV)window.__FORM__={world,state,journal,review,activityDom,audio:courseSound,stations,exercises:qualifiedExercises,activities:exercises,catalogActivities,openExercise,openStation,targetExercise,mobileControls,mobileUI};
  function frame(now){const rawDt=Math.max(0,(now-lastTime)/1000);lastTime=now;if(!document.hidden){world.recordFrameTiming(rawDt*1000);let remaining=Math.min(rawDt,.15);while(remaining>.05){world.update(.05,false,{deferAmbient:true});remaining-=.05;}world.update(remaining,true);}if(now-lastMap>80){const p=world.getPlayerPosition(),s=station(state.targetId);updateMaps(p,world.getHeading(),s);const el=document.querySelector('#target-distance');if(el&&s)el.textContent=`${Math.round(Math.hypot(p.x-s.position.x,p.z-s.position.z))} m`;lastMap=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);window.addEventListener('resize',()=>world.resize());document.addEventListener('visibilitychange',()=>{lastTime=performance.now();if(document.hidden){courseSound.stop();world.stopPerformanceCheck('分頁離開前景，請重新測量。');}});
}catch(error){console.error(error);state.error='無法載入真人模型，請確認網頁伺服器及模型檔案後重新載入。';render();}
